#include <vector>
#include <string>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int longestCommonPrefix(std::vector<int>& arr1, std::vector<int>& arr2) {
        std::unordered_set<std::string> prefixes;
        for (int x : arr1) {
            std::string s = std::to_string(x);
            for (size_t l = 1; l <= s.size(); ++l) prefixes.insert(s.substr(0, l));
        }
        int ans = 0;
        for (int y : arr2) {
            std::string s = std::to_string(y);
            for (int l = s.size(); l > 0; --l) {
                if (prefixes.count(s.substr(0, l))) {
                    ans = std::max(ans, l);
                    break;
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int longestCommonPrefix(int[] arr1, int[] arr2) {
        Set<String> prefixes = new HashSet<>();
        for (int x : arr1) {
            String s = Integer.toString(x);
            for (int l = 1; l <= s.length(); ++l) prefixes.add(s.substring(0, l));
        }
        int ans = 0;
        for (int y : arr2) {
            String s = Integer.toString(y);
            for (int l = s.length(); l > 0; --l) {
                if (prefixes.contains(s.substring(0, l))) {
                    ans = Math.max(ans, l);
                    break;
                }
            }
        }
        return ans;
    }
}

